* { box-sizing: border-box; }

body {
     margin: 0;
     font-family: Arial, "Segoe UI", sans-serif;
     background: #eceff1;
}

.khung-4-vung {
     max-width: 1080px;
     margin: 0 auto;
     min-height: 600px;
     display: grid;
     grid-template-columns: 200px 1fr 160px;
     grid-template-rows: auto 1fr;
     grid-template-areas:
       "banner banner banner"
       "menu      main   qc";
     background: #ffffff;
     box-shadow: 0 0 24px rgba(0, 0, 0, 0.1);
}

.banner {
     grid-area: banner;

    background: #C62828 url("assets/Nen_banner.jpg") center / cover;
    color: #ffffff;
    padding: 16px 22px;
    display: flex;
    align-items: center;
    gap: 16px;
}

.banner img { height: 42px; }

.banner h1 {
    margin: 0;
    font-size: clamp(18px, 2.2vw, 22px);
    text-shadow: 1px 1px 3px rgba(0, 0, 0, 0.6);
}

.menu-doc {
    grid-area: menu;
    background: linear-gradient(180deg, #C62828, #8E0000);
    padding: 12px 0;
}

.menu-doc a {
    display: block;
    color: #ffffff;
    text-decoration: none;
    padding: 12px 16px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.2);
    font-size: 14px;
}

.menu-doc a:hover { background: rgba(0, 0, 0, 0.2); }

main {
    grid-area: main;
    padding: 22px;
}

main h2 {
    color: #C62828;
    margin: 0 0 14px;
}

.hop-vang {
    background: #FFE082;
    border-radius: 6px;
    padding: 12px 16px;
    margin-bottom: 18px;
}

.hop-vang ul {
    margin: 0;
    padding-left: 20px;
    display: flex;
    flex-wrap: wrap;
    gap: 4px 24px;
}

.khung-nd {
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    padding: 16px;
    line-height: 1.7;
}

.quang-cao {
    grid-area: qc;
    padding: 16px 12px;
    display: flex;
    flex-direction: column;
    gap: 14px;
    border-left: 1px solid #f0f0f0;
}

.quang-cao img {
    width: 100%;

     border: 1px solid #eeeeee;
     border-radius: 6px;
     display: block;
}

@media (max-width: 820px) {
     .khung-4-vung {
         grid-template-columns: 1fr;
         grid-template-areas:
           "banner"
           "menu"
           "main"
           "qc";
     }
     .menu-doc { display: flex; flex-wrap: wrap; padding: 0; }
     .menu-doc a { border-bottom: none; border-right: 1px solid rgba(255, 255, 255, 0.2); }
     .quang-cao { flex-direction: row; }
     .quang-cao img { width: 50%; }
}
